import * as React from "react";
import { Dialog as DialogPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";
import { Button } from "./button";
import { Icon } from "./icon";

import { FrameScope } from "../lib/frame-context";
import { OverlayPendingContext, useDismissGuard, useOverlayPending } from "../lib/overlay-pending";
import { renderInForm, splitOverlaySections } from "../lib/overlay-sections";
import { useOwnedEscape } from "../lib/use-owned-escape";
import { cn } from "../lib/utils";

import overlay from "./overlay.module.css";

function Dialog({ ...props }: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />;
}

function DialogTrigger({ ref, ...props }: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger ref={ref} data-slot="dialog-trigger" {...props} />;
}
DialogTrigger.displayName = "DialogTrigger";

function DialogPortal({ children, ...props }: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return (
    <DialogPrimitive.Portal container={useV4PortalContainer()} data-slot="dialog-portal" {...props}>
      <FrameScope framed={false}>{children}</FrameScope>
    </DialogPrimitive.Portal>
  );
}

function DialogClose({
  ref,
  disabled,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Close>) {
  const pending = useOverlayPending();
  return (
    <DialogPrimitive.Close
      ref={ref}
      data-slot="dialog-close"
      disabled={disabled || pending}
      {...props}
    />
  );
}
DialogClose.displayName = "DialogClose";

function DialogOverlay({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      ref={ref}
      data-slot="dialog-overlay"
      className={cn("isolate z-50", overlay.scrim, className)}
      {...props}
    />
  );
}
DialogOverlay.displayName = "DialogOverlay";

function DialogContent({
  className,
  children,
  showCloseButton = true,
  pending = false,
  onEscapeKeyDown,
  onPointerDownOutside,
  onInteractOutside,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean;
  /** While true, Escape, outside clicks and every close control are blocked, so an in-flight save cannot be abandoned. */
  pending?: boolean;
} & { ref?: React.Ref<React.ComponentRef<typeof DialogPrimitive.Content>> }) {
  const escape = useOwnedEscape(ref, onEscapeKeyDown);
  const guard = useDismissGuard(pending, {
    onEscapeKeyDown: escape.onEscapeKeyDown,
    onPointerDownOutside,
    onInteractOutside
  });
  const sections = splitOverlaySections(
    children,
    {
      header: DialogHeader,
      subheader: DialogSubheader,
      footer: DialogFooter
    },
    { pinHeader: true, lookThroughForm: true }
  );
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        ref={escape.ref}
        data-slot="dialog-content"
        data-has-close={showCloseButton || undefined}
        data-scroll-fade={sections ? undefined : "y"}
        data-sections={sections ? "" : undefined}
        aria-busy={pending || undefined}
        className={cn("z-50", overlay.pop, overlay.dialog, className)}
        {...props}
        {...guard}
      >
        <OverlayPendingContext value={pending}>
          {sections
            ? renderInForm(
                sections.form,
                "dialog-form",
                <>
                  {sections.pinned.length > 0 && (
                    <div data-slot="dialog-head">{sections.pinned}</div>
                  )}
                  {sections.scroll.length > 0 && (
                    <div
                      data-slot="dialog-scroll"
                      data-scroll-fade="y"
                      data-before-footer={sections.footer.length > 0 || undefined}
                    >
                      {sections.scroll}
                    </div>
                  )}
                  {sections.footer}
                </>
              )
            : children}
          {showCloseButton && (
            <DialogPrimitive.Close data-slot="dialog-close" asChild>
              <Button variant="ghost" className={overlay.close} size="icon-sm" disabled={pending}>
                <Icon name="x" />
                <span className="sr-only">Close</span>
              </Button>
            </DialogPrimitive.Close>
          )}
        </OverlayPendingContext>
      </DialogPrimitive.Content>
    </DialogPortal>
  );
}
DialogContent.displayName = "DialogContent";

function DialogHeader({ className, ref, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      ref={ref}
      data-slot="dialog-header"
      className={cn("flex flex-col gap-2", className)}
      {...props}
    />
  );
}
DialogHeader.displayName = "DialogHeader";

function DialogSubheader({ className, ref, ...props }: React.ComponentProps<"div">) {
  return <div ref={ref} data-slot="dialog-subheader" className={cn(className)} {...props} />;
}
DialogSubheader.displayName = "DialogSubheader";

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<"div"> & {
  showCloseButton?: boolean;
} & { ref?: React.Ref<React.ComponentRef<"div">> }) {
  return (
    <div
      ref={ref}
      data-slot="dialog-footer"
      className={cn("flex flex-col-reverse sm:flex-row sm:justify-end", className)}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogClose asChild>
          <Button variant="outline">Close</Button>
        </DialogClose>
      )}
    </div>
  );
}
DialogFooter.displayName = "DialogFooter";

function DialogTitle({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      ref={ref}
      data-slot="dialog-title"
      className={cn("", className)}
      {...props}
    />
  );
}
DialogTitle.displayName = "DialogTitle";

function DialogDescription({
  className,
  ref,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      ref={ref}
      data-slot="dialog-description"
      className={cn(
        "text-muted-foreground *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
        className
      )}
      {...props}
    />
  );
}
DialogDescription.displayName = "DialogDescription";

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogSubheader,
  DialogTitle,
  DialogTrigger
};

.scrim {
  position: fixed;
  inset: 0;
  background-color: var(--v4-scrim);
}
.scrim[data-state="open"] {
  animation: fadeIn var(--v4-duration-slow) var(--v4-ease-fade) both;
}
.scrim[data-state="closed"] {
  animation: fadeOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.pop {
  box-sizing: border-box;
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  white-space: normal;
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
}
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.dialog {
  position: fixed;
  top: 50%;
  left: 50%;
  display: grid;
  width: calc(100% - 2 * var(--v4-space-16));
  max-width: var(--v4-size-dialog);
  max-height: calc(100dvh - 2 * var(--v4-size-overlay-margin));
  overflow-y: auto;
  translate: -50% -50%;
}
.dialog[data-sections] {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.dialog[data-state="open"] {
  animation: dialogIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.dialog[data-state="closed"] {
  animation: dialogOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
.palette {
  --v4-palette-top: clamp(var(--v4-space-48), 13vh, calc(3 * var(--v4-space-48)));
  top: var(--v4-palette-top);
  display: flex;
  flex-direction: column;
  max-width: var(--v4-size-dialog-wide);
  max-height: calc(100dvh - var(--v4-palette-top) - var(--v4-space-16));
  overflow: hidden;
  translate: -50% 0;
}
.palette [cmdk-root] {
  min-height: 0;
}
.palette [data-slot="command-scroll"] {
  flex: 0 1 auto;
  min-height: 0;
}
.palette [cmdk-item] {
  min-height: var(--v4-size-control-md);
}
.close[data-slot] {
  position: absolute;
  top: calc(
    var(--v4-dialog-pad, var(--v4-space-overlay-inset)) +
      (var(--v4-type-title-line-height) - var(--v4-size-nested-md)) / 2
  );
  inset-inline-end: calc(
    var(--v4-dialog-pad, var(--v4-space-overlay-inset)) -
      (var(--v4-size-nested-md) - var(--v4-size-icon)) / 2
  );
}
.sheet {
  --v4-sheet-from: 100% 0;
  --v4-sheet-size: var(--v4-size-sheet-sm);
}
.sheet[data-size="md"] {
  --v4-sheet-size: var(--v4-size-sheet-md);
}
.sheet[data-size="lg"] {
  --v4-sheet-size: var(--v4-size-sheet-lg);
}
.sheet[data-side="left"],
.sheet[data-side="right"] {
  max-width: min(var(--v4-sheet-size), 100vw);
}
.sheet[data-side="left"] {
  --v4-sheet-from: -100% 0;
}
.sheet[data-side="top"] {
  --v4-sheet-from: 0 -100%;
}
.sheet[data-side="bottom"] {
  --v4-sheet-from: 0 100%;
}
.sheet[data-state="open"] {
  animation: sheetIn var(--v4-duration-slow) var(--v4-ease-spring-soft) both;
}
.sheet[data-state="closed"] {
  animation: sheetOut var(--v4-duration-exit-slow) var(--v4-ease-exit) both;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@keyframes dialogIn {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes dialogOut {
  to {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes sheetIn {
  from {
    translate: var(--v4-sheet-from);
  }
}
@keyframes sheetOut {
  to {
    translate: var(--v4-sheet-from);
  }
}
@media (prefers-reduced-motion: reduce) {
  .dialog[data-state="open"],
  .sheet[data-state="open"] {
    animation-name: fadeIn;
  }
  .dialog[data-state="closed"],
  .sheet[data-state="closed"] {
    animation-name: fadeOut;
  }
}
